import { runRuleTests } from "../testing/run-rule-tests.ts";
import rule from "./no-position-markers.ts";

runRuleTests("no-position-markers", rule, {
  valid: [
    { name: "a run between two other characters is part of a token, so `*=====/` is never joined into `*/`", code: "/* a *=====/ b */\nexport const h = 9;" },
    { name: "review: an ASCII box diagram", code: "// +--------+     +--------+\n// | parser | --> | linter |\n// +--------+     +--------+\nexport const pipeline = 2;" },
    { name: "review: a box-drawing diagram", code: "// \u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n// \u2502 node \u2502\n// \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n// |=======|\nexport const box = 1;" },
    { name: "review: a run inside a base64 token", code: "// data: eyJ2/////ZXJzaW9uIjozfQ==\nexport const map = 1;" },
    { name: "review: an inline source map is a directive", code: "export const a = 1;\n//# sourceMappingURL=data:application/json;base64,eyJ2/////ZXJz\n" },
    { name: "review: a sourceURL and an old-style source map are directives", code: "export const a = 1;\n//# sourceURL=a-----b.js\n//@ sourceMappingURL=x=====y.map\n" },
    { name: "a legal header (CMT-02)", code: "/*\n * Copyright (c) 2024 Acme Corp. All rights reserved.\n * Licensed under the Apache License, Version 2.0.\n */\nexport const a = 1;" },
    { name: "a regular-expression explanation (CMT-02)", code: "// Matches a rule line such as `----` or `====`: four or more of one character.\nconst rule = /^(-{4,}|={4,})$/;" },
    { name: "a \"why\" comment (CMT-02)", code: "// We retry once because the first request after a deploy is dropped by the proxy.\nretry(send);" },
    { name: "JSDoc's opening `/**`", code: "/**\n * Parses the file.\n */\nexport function parse() {}" },
    { name: "a `/****` opening one short of a run", code: "/***** Parses the file. */\nexport function parse() {}" },
    { name: "four characters are under the threshold", code: "// ---- setup ----\nrun();" },
    { name: "an arrow", code: "// [A] -----> [B] <===== [C]\nrun();" },
    { name: "a Markdown heading underline in a doc comment", code: "/**\n * Usage\n * =====\n *\n * Details\n * -------\n */\nexport function f() {}" },
    { name: "a Markdown table rule in a doc comment", code: "/**\n * | Name  | Value |\n * | ----- | ----- |\n * | a     | 1     |\n */\nexport function f() {}" },
    { name: "a directive comment is never changed", code: "/*! ========== v1.0.0 ========== */\nrun();" },
    { name: "directive comments are left alone", code: "// eslint-disable-next-line no-console\nconsole.log(1);" },
    { name: "a longer threshold", options: [8], code: "// ------ setup ------\nrun();" },
  ],
  invalid: [
    {
      name: "the book's train of slashes",
      code: "// Actions //////////////////////////////////\nexport const a = 1;",
      output: "// Actions\nexport const a = 1;",
      errors: [{ messageId: "banner", data: { count: "34", character: "/" } }],
      behaviour: "a",
    },
    {
      name: "a banner with text between two runs keeps the text",
      code: "// ===== Section =====\nexport const b = 2;",
      output: "// Section\nexport const b = 2;",
      errors: 1,
      behaviour: "b",
    },
    {
      name: "a banner with no space after `//`",
      code: "//===== Section\nexport const b = 3;",
      output: "// Section\nexport const b = 3;",
      errors: 1,
      behaviour: "b",
    },
    {
      name: "a comment that is only a run goes as a whole",
      code: "const a = 1;\n//////////////////////////\nexport const b = a;",
      output: "const a = 1;\nexport const b = a;",
      errors: 1,
      behaviour: "b",
    },
    {
      name: "a block banner keeps its text",
      code: "/*******************\n * Section\n *******************/\nexport const c = 4;",
      output: "/*\n * Section\n */\nexport const c = 4;",
      errors: 1,
      behaviour: "c",
    },
    {
      name: "a one-line block banner stays a plain comment, not a doc comment",
      code: "/********** Section **********/\nexport const c = 5;",
      output: "/* Section */\nexport const c = 5;",
      errors: 1,
      behaviour: "c",
    },
    {
      name: "a run above a doc heading is not an underline",
      code: "/**\n * ==========\n * Usage\n * =====\n */\nexport function f() { return 1; }",
      output: "/**\n * Usage\n * =====\n */\nexport function f() { return 1; }",
      errors: 1,
      behaviour: "f()",
    },
    {
      name: "a run of `#` and of `-` in a block",
      code: "/* ##### helpers -------- */\nexport const d = 6;",
      output: "/* helpers */\nexport const d = 6;",
      errors: 1,
      behaviour: "d",
    },
    {
      name: "a trailing banner goes with the space before it",
      code: "export const e = 7; // ==========",
      output: "export const e = 7;",
      errors: 1,
      behaviour: "e",
    },
    {
      name: "regression: a `;[1, 2]` line after a banner, in code without semicolons, keeps its `;`",
      code: "let r = 0\n// ==========\n;[1, 2].forEach((v) => { r += v })",
      output: "let r = 0\n;[1, 2].forEach((v) => { r += v })",
      errors: 1,
      behaviour: "r",
    },
    {
      name: "a banner between `return` and its value, across lines, becomes a line break",
      code: "function f() {\n  return /* ==========\n  ========== */ 42\n}",
      output: "function f() {\n  return \n 42\n}",
      errors: 1,
      behaviour: ["f()", "typeof f()"],
    },
    {
      name: "`return/*=====*/value` keeps a space",
      code: "function f(value) { return/*=====*/value }",
      output: "function f(value) { return value }",
      errors: 1,
      behaviour: "[1, 'a'].map((v) => f(v))",
    },
    {
      name: "a shorter threshold",
      options: [3],
      code: "// --- setup ---\nexport const g = 8;",
      output: "// setup\nexport const g = 8;",
      errors: 1,
      behaviour: "g",
    },
  ],
});
